<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Humanoid Treadmill Animation</title>
<style>
  * { margin: 0; padding: 0; }
  body { overflow: hidden; background: #1a1a2e; }
  canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{ "imports": { "three": "./three.module.js" } }
</script>
<script type="module">
import * as THREE from './three.module.js';

// ── Setup ───────────────────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.Fog(0x1a1a2e, 15, 30);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1.8, 7);
camera.lookAt(0, 1.2, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

// ── Materials ───────────────────────────────────────────────────────
const matHead = new THREE.MeshStandardMaterial({ color: 0xe8b88a, roughness: 0.8 });
const matBody = new THREE.MeshStandardMaterial({ color: 0x2a5f8f, roughness: 0.7 });
const matPants = new THREE.MeshStandardMaterial({ color: 0x3d3d3d, roughness: 0.6 });
const matShoes = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.5 });
const matSkin = new THREE.MeshStandardMaterial({ color: 0xe8b88a, roughness: 0.8 });

// ── Build humanoid ──────────────────────────────────────────────────
const human = new THREE.Group();
human.position.set(0, 0, 0);
scene.add(human);

// Head
const head = new THREE.Group();
head.position.set(0, 1.55, 0);
human.add(head);
const headMesh = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.32, 0.28), matHead);
headMesh.position.y = 0;
head.add(headMesh);

// Torso
const torso = new THREE.Group();
torso.position.set(0, 1.05, 0);
human.add(torso);
const torsoMesh = new THREE.Mesh(new THREE.BoxGeometry(0.45, 0.55, 0.28), matBody);
torso.add(torsoMesh);

// Head pivot (for lean)
const headPivot = new THREE.Group();
headPivot.position.set(0, 1.55, 0);
human.add(headPivot);
headPivot.add(head);

// Left arm
const leftArm = new THREE.Group();
leftArm.position.set(-0.32, 1.35, 0);
human.add(leftArm);
const upperArmL = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.32, 0.11), matBody);
upperArmL.position.y = -0.16;
leftArm.add(upperArmL);
const lowerArmL = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.28, 0.09), matSkin);
lowerArmL.position.y = -0.46;
leftArm.add(lowerArmL);

// Right arm
const rightArm = new THREE.Group();
rightArm.position.set(0.32, 1.35, 0);
human.add(rightArm);
const upperArmR = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.32, 0.11), matBody);
upperArmR.position.y = -0.16;
rightArm.add(upperArmR);
const lowerArmR = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.28, 0.09), matSkin);
lowerArmR.position.y = -0.46;
rightArm.add(lowerArmR);

// Left leg
const leftLeg = new THREE.Group();
leftLeg.position.set(-0.12, 0.78, 0);
human.add(leftLeg);
const upperLegL = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.42, 0.16), matPants);
upperLegL.position.y = -0.21;
leftLeg.add(upperLegL);
const lowerLegL = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.42, 0.13), matPants);
lowerLegL.position.y = -0.61;
leftLeg.add(lowerLegL);
const shoeL = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.08, 0.28), matShoes);
shoeL.position.set(0, -0.85, 0.05);
leftLeg.add(shoeL);

// Right leg
const rightLeg = new THREE.Group();
rightLeg.position.set(0.12, 0.78, 0);
human.add(rightLeg);
const upperLegR = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.42, 0.16), matPants);
upperLegR.position.y = -0.21;
rightLeg.add(upperLegR);
const lowerLegR = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.42, 0.13), matPants);
lowerLegR.position.y = -0.61;
rightLeg.add(lowerLegR);
const shoeR = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.08, 0.28), matShoes);
shoeR.position.set(0, -0.85, 0.05);
rightLeg.add(shoeR);

// ── Treadmill ───────────────────────────────────────────────────────
const belt = new THREE.Mesh(
  new THREE.BoxGeometry(3, 0.08, 1.6),
  new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.9 })
);
belt.position.set(0, 0.04, 0);
scene.add(belt);

const beltSurface = new THREE.Mesh(
  new THREE.BoxGeometry(3, 0.02, 1.6),
  new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.6 })
);
beltSurface.position.set(0, 0.1, 0);
scene.add(beltSurface);

// Treadmill rails
for (let x of [-0.85, 0.85]) {
  const rail = new THREE.Mesh(
    new THREE.BoxGeometry(0.06, 0.06, 1.6),
    new THREE.MeshStandardMaterial({ color: 0x444444 })
  );
  rail.position.set(x, 0.07, 0);
  scene.add(rail);
}

// Belt texture lines that scroll
const lineMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
const beltLines = [];
for (let i = -4; i <= 4; i++) {
  const line = new THREE.Mesh(
    new THREE.BoxGeometry(0.02, 0.02, 1.4),
    lineMat
  );
  line.position.set(i * 0.45, 0.11, 0);
  scene.add(line);
  beltLines.push(line);
}

// ── Lighting ──────────────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0x404060, 0.6));
const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(3, 5, 5);
scene.add(dirLight);
const fillLight = new THREE.DirectionalLight(0x8888ff, 0.3);
fillLight.position.set(-3, 2, -2);
scene.add(fillLight);

// ── Animation ─────────────────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const cycle = t % 10; // 10-second cycle

  // Phase states
  let state = 'stand';
  let phaseT = 0;
  if (cycle < 2) {
    state = 'stand';
    phaseT = cycle;
  } else if (cycle < 5) {
    state = 'walk';
    phaseT = cycle - 2;
  } else if (cycle < 8) {
    state = 'run';
    phaseT = cycle - 5;
  } else {
    state = 'stand';
    phaseT = cycle - 8;
  }

  const speed = state === 'walk' ? 4.5 : 7.5;
  const amplitude = state === 'walk' ? 0.45 : 0.75;
  const lean = state === 'run' ? 0.12 : 0;
  const armSwing = state === 'walk' ? 0.5 : 0.85;
  const bodyBob = state === 'walk' ? 0.025 : 0.055;

  // Apply head lean
  headPivot.rotation.z = 0;
  headPivot.rotation.x = lean;

  // Apply body lean via torso
  torso.rotation.x = lean * 0.5;

  // Phase within cycle for swing
  const phase = phaseT * speed;

  if (state === 'stand') {
    // Reset all to neutral
    leftArm.rotation.x = 0;
    rightArm.rotation.x = 0;
    leftLeg.rotation.x = 0;
    rightLeg.rotation.x = 0;
    headPivot.rotation.x = 0;
    torso.rotation.x = 0;
    headPivot.rotation.z = 0;
  } else {
    const s = Math.sin(phase * Math.PI);
    const c = Math.cos(phase * Math.PI);

    // Arms swing opposite to legs
    leftArm.rotation.x = s * armSwing;
    rightArm.rotation.x = -s * armSwing;

    // Legs swing
    leftLeg.rotation.x = -s * amplitude;
    rightLeg.rotation.x = s * amplitude;
  }

  // Body bob
  const bob = state === 'stand' ? 0 : Math.abs(Math.sin(phase * Math.PI)) * bodyBob;
  human.position.y = bob;

  // Treadmill belt lines scroll
  for (const line of beltLines) {
    line.position.x += (state === 'stand' ? 0 : -0.08);
    if (line.position.x < -2) line.position.x += 3.6;
  }

  renderer.render(scene, camera);
}

// ── Resize ────────────────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

animate();
</script>
</body>
</html>
